#!/usr/bin/env python3
"""Aurora: degistirilebilir uygulama simgesi (Android activity-alias).
cap add android + cap sync SONRASI calistirilir. Bir sey ters giderse build'i durdurur."""
import base64, glob, os, re, sys

ROOT = os.getcwd()
ANDROID = os.path.join(ROOT, 'android', 'app', 'src', 'main')
RES = os.path.join(ANDROID, 'res')
MANIFEST = os.path.join(ANDROID, 'AndroidManifest.xml')
ICONS = [
  {'id': 'rengarenk', 'bg': '#DDDDDF',
   'fg': '',
   'legacy': ''},
  {'id': 'holografik', 'bg': '#DEDFE1',
   'fg': '',
   'legacy': ''},
  {'id': 'mercan', 'bg': '#E1E1E1',
   'fg': '',
   'legacy': ''},
  {'id': 'cizgi', 'bg': '#FFFFFF',
   'fg': '',
   'legacy': ''}
]
DEFAULT = ICONS[0]['id']

def die(msg):
    print('HATA:', msg); sys.exit(1)

def put(path, data, binary=False):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb' if binary else 'w', **({} if binary else {'encoding': 'utf-8'})) as f:
        f.write(data)

# 1) MainActivity ve paket adi
found = glob.glob(os.path.join(ANDROID, 'java', '**', 'MainActivity.java'), recursive=True)
if len(found) != 1: die('MainActivity.java bulunamadi: %s' % found)
main_path = found[0]
pkg = re.search(r'^\s*package\s+([\w.]+)\s*;', open(main_path, encoding='utf-8').read(), re.M)
if not pkg: die('MainActivity paket adi okunamadi')
pkg = pkg.group(1); jdir = os.path.dirname(main_path)

# 2) simge kaynaklari
colors = ['<?xml version="1.0" encoding="utf-8"?>', '<resources>']
for ic in ICONS:
    i = ic['id']
    put(os.path.join(RES, 'drawable-xxxhdpi', 'ic_fg_%s.jpg' % i), base64.b64decode(ic['fg']), True)
    put(os.path.join(RES, 'mipmap-xxxhdpi', 'ic_launcher_%s.jpg' % i), base64.b64decode(ic['legacy']), True)
    put(os.path.join(RES, 'mipmap-anydpi-v26', 'ic_launcher_%s.xml' % i),
        '<?xml version="1.0" encoding="utf-8"?>\n<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">\n'
        '  <background android:drawable="@color/ic_bg_%s"/>\n  <foreground android:drawable="@drawable/ic_fg_%s"/>\n</adaptive-icon>\n' % (i, i))
    colors.append('  <color name="ic_bg_%s">%s</color>' % (i, ic['bg']))
colors.append('</resources>')
put(os.path.join(RES, 'values', 'ic_alias_colors.xml'), '\n'.join(colors) + '\n')

# 3) manifest: ana activity'den LAUNCHER'i kaldir, alias'lari ekle
m = open(MANIFEST, encoding='utf-8').read()
launcher = re.compile(r'<intent-filter>\s*<action android:name="android\.intent\.action\.MAIN"\s*/>\s*<category android:name="android\.intent\.category\.LAUNCHER"\s*/>\s*</intent-filter>')
if len(launcher.findall(m)) != 1: die('MainActivity LAUNCHER filtresi bulunamadi')
m = launcher.sub('', m, count=1)
aliases = ''
for ic in ICONS:
    i = ic['id']; cls = 'Icon' + i.capitalize()
    aliases += ('\n        <activity-alias android:name="%s.%s" android:targetActivity="%s.MainActivity" android:enabled="%s" android:exported="true"'
                ' android:label="@string/app_name" android:icon="@mipmap/ic_launcher_%s" android:roundIcon="@mipmap/ic_launcher_%s">'
                '\n            <intent-filter>\n                <action android:name="android.intent.action.MAIN" />\n'
                '                <category android:name="android.intent.category.LAUNCHER" />\n            </intent-filter>\n        </activity-alias>'
                % (pkg, cls, pkg, 'true' if i == DEFAULT else 'false', i, i))
if '</application>' not in m: die('</application> yok')
m = m.replace('</application>', aliases + '\n    </application>', 1)
if m.count('android.intent.category.LAUNCHER') != len(ICONS): die('LAUNCHER sayisi beklenenden farkli')
put(MANIFEST, m)

# 4) eklenti + MainActivity
ids = ', '.join('"%s"' % i['id'] for i in ICONS)
put(os.path.join(jdir, 'AuroraIconPlugin.java'), '''package %(pkg)s;

import android.content.ComponentName;
import android.content.pm.PackageManager;
import com.getcapacitor.JSObject;
import com.getcapacitor.Plugin;
import com.getcapacitor.PluginCall;
import com.getcapacitor.PluginMethod;
import com.getcapacitor.annotation.CapacitorPlugin;

@CapacitorPlugin(name = "AuroraIcon")
public class AuroraIconPlugin extends Plugin {
    private static final String[] IDS = {%(ids)s};
    private static final String DEFAULT = "%(default)s";

    private ComponentName cn(String id) {
        String cls = "Icon" + Character.toUpperCase(id.charAt(0)) + id.substring(1);
        return new ComponentName(getContext().getPackageName(), "%(pkg)s." + cls);
    }

    private String current() {
        PackageManager pm = getContext().getPackageManager();
        for (String id : IDS) {
            int s = pm.getComponentEnabledSetting(cn(id));
            if (s == PackageManager.COMPONENT_ENABLED_STATE_ENABLED
                || (s == PackageManager.COMPONENT_ENABLED_STATE_DEFAULT && id.equals(DEFAULT))) return id;
        }
        return DEFAULT;
    }

    @PluginMethod
    public void get(PluginCall call) {
        JSObject r = new JSObject();
        r.put("name", current());
        call.resolve(r);
    }

    @PluginMethod
    public void set(PluginCall call) {
        String name = call.getString("name");
        boolean ok = false;
        for (String id : IDS) if (id.equals(name)) ok = true;
        if (!ok) { call.reject("bilinmeyen simge"); return; }
        try {
            PackageManager pm = getContext().getPackageManager();
            // once yenisini ac, sonra digerlerini kapat: her an en az bir simge acik kalir
            pm.setComponentEnabledSetting(cn(name), PackageManager.COMPONENT_ENABLED_STATE_ENABLED, PackageManager.DONT_KILL_APP);
            for (String id : IDS) if (!id.equals(name))
                pm.setComponentEnabledSetting(cn(id), PackageManager.COMPONENT_ENABLED_STATE_DISABLED, PackageManager.DONT_KILL_APP);
            JSObject r = new JSObject(); r.put("name", current());
            call.resolve(r);
        } catch (Exception e) {
            call.reject("simge degistirilemedi: " + e.getMessage());
        }
    }
}
''' % {'pkg': pkg, 'ids': ids, 'default': DEFAULT})
put(main_path, '''package %s;

import android.os.Bundle;
import com.getcapacitor.BridgeActivity;

public class MainActivity extends BridgeActivity {
    @Override
    public void onCreate(Bundle savedInstanceState) {
        registerPlugin(AuroraIconPlugin.class);
        super.onCreate(savedInstanceState);
    }
}
''' % pkg)
print('Tamam: paket=%s, simgeler=%s' % (pkg, [i['id'] for i in ICONS]))
